#!/bin/sh
# Stand-in for pip-compile / npm install / bundle lock.
{
  echo '# generated from requirements.in — do not edit'
  {
    while read -r pkg; do
      [ -n "$pkg" ] || continue
      case "$pkg" in
        flask) printf 'blinker==1.7.0\nclick==8.1.7\nflask==3.0.0\nitsdangerous==2.1.2\njinja2==3.1.3\nmarkupsafe==2.1.5\nwerkzeug==3.0.1\n' ;;
        redis) printf 'redis==5.0.1\n' ;;
        celery) printf 'amqp==5.2.0\nbilliard==4.2.0\ncelery==5.3.6\nkombu==5.3.5\nvine==5.1.0\n' ;;
        *) printf '%s==0.0.0\n' "$pkg" ;;
      esac
    done < requirements.in
  } | sort -u
} > requirements.lock
echo "regenerated requirements.lock"
